import React, { useState, useEffect, useMemo } from 'react';
import {
  Users,
  Loader2,
  AlertCircle,
  RefreshCw,
  Medal,
} from 'lucide-react';
import {
  loadLeaderboard,
  bestPerPerson,
} from './supabase.js';

const LOGO_URL = "data:image/png;base64,";

function formatDateTime(ts) {
  const d = new Date(ts);
  return d.toLocaleString(undefined, {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

function LogoBadge() {
  return (
    <img
      src={LOGO_URL}
      alt="Western Steel Buildings"
      className="h-10 md:h-12 w-auto object-contain"
      style={{ background: 'transparent' }}
    />
  );
}

export default function ScoreboardPage() {
  const [attempts, setAttempts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // The three views requested:
  //  - 'topscore'    : best percentage per person, sorted high to low
  //  - 'recent'      : every attempt, most recent first
  //  - 'byperson'    : every attempt, grouped alphabetically by name
  const [sortMode, setSortMode] = useState('topscore');

  const refresh = async () => {
    setLoading(true);
    setError('');
    try {
      const result = await loadLeaderboard();
      if (result.error) {
        setError(`Couldn't load scores: ${result.error.message}`);
        setAttempts([]);
      } else {
        setAttempts(result.data);
      }
    } catch (err) {
      setError(`Unexpected error: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refresh();
  }, []);

  const stats = useMemo(() => {
    if (attempts.length === 0) {
      return { totalAttempts: 0, uniquePeople: 0, averagePct: 0, highScore: null };
    }
    const uniqueNames = new Set(
      attempts.map((a) => (a.name || '').trim().toLowerCase())
    );
    const avg =
      attempts.reduce((sum, a) => sum + a.score / a.total, 0) / attempts.length;
    const highScoreAttempt = attempts.reduce((best, a) => {
      const pct = a.score / a.total;
      const bestPct = best ? best.score / best.total : -1;
      return pct > bestPct ? a : best;
    }, null);
    return {
      totalAttempts: attempts.length,
      uniquePeople: uniqueNames.size,
      averagePct: Math.round(avg * 100),
      highScore: highScoreAttempt,
    };
  }, [attempts]);

  // Produce the rows to render for the current sort mode.
  const visibleRows = useMemo(() => {
    if (sortMode === 'topscore') {
      // Best percentage per person, ranked
      return bestPerPerson(attempts);
    }
    if (sortMode === 'recent') {
      // Every attempt, most recent first
      return [...attempts].sort(
        (a, b) => new Date(b.created_at) - new Date(a.created_at)
      );
    }
    if (sortMode === 'byperson') {
      // Every attempt, sorted alphabetically by name then by date (newest first within each name)
      return [...attempts].sort((a, b) => {
        const nameCmp = (a.name || '').toLowerCase().localeCompare((b.name || '').toLowerCase());
        if (nameCmp !== 0) return nameCmp;
        return new Date(b.created_at) - new Date(a.created_at);
      });
    }
    return attempts;
  }, [attempts, sortMode]);

  // For the "by person" view, figure out where the name changes so we can
  // visually separate each person's attempts.
  const nameStartIndices = useMemo(() => {
    if (sortMode !== 'byperson') return new Set();
    const starts = new Set();
    let lastName = null;
    visibleRows.forEach((row, idx) => {
      const norm = (row.name || '').trim().toLowerCase();
      if (norm !== lastName) {
        starts.add(idx);
        lastName = norm;
      }
    });
    return starts;
  }, [visibleRows, sortMode]);

  const SORT_OPTIONS = [
    { key: 'topscore', label: 'Top Score', description: 'Best per person, ranked' },
    { key: 'recent', label: 'Most Recent', description: 'Every attempt, newest first' },
    { key: 'byperson', label: 'By Person', description: 'Grouped alphabetically' },
  ];

  return (
    <div
      className="min-h-screen"
      style={{
        background: '#0a0a0a',
        color: '#f5f1ea',
        fontFamily: '"Manrope", system-ui, sans-serif',
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&family=Oswald:wght@400;500;600;700&display=swap');
        .font-display { font-family: 'Oswald', sans-serif; letter-spacing: 0.02em; }
      `}</style>

      <div className="w-full px-6 md:px-12 lg:px-20 py-10 md:py-12">
        {/* Header */}
        <div className="flex items-center justify-between mb-10 gap-3 flex-wrap">
          <div className="flex items-center gap-4">
            <LogoBadge />
            <div className="hidden md:block w-px h-10 bg-white/10" />
            <div className="hidden md:block text-xs uppercase tracking-[0.3em] opacity-60">
              SOP Quiz Scoreboard
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={refresh}
              disabled={loading}
              className="flex items-center gap-2 px-3 py-2 text-xs uppercase tracking-widest border border-white/10 hover:bg-white/5 transition-colors disabled:opacity-50"
            >
              <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
              Refresh
            </button>
            <a
              href="/"
              className="text-xs uppercase tracking-widest opacity-60 hover:opacity-100 transition-opacity"
            >
              ← Take the quiz
            </a>
          </div>
        </div>

        <div className="diag-stripes h-2 mb-8" style={{
          background: 'repeating-linear-gradient(135deg, #f47820, #f47820 12px, transparent 12px, transparent 24px)',
        }} />

        <h1 className="font-display text-5xl md:text-7xl font-bold uppercase leading-none tracking-tight mb-4">
          SOP Quiz Scoreboard
        </h1>
        <p className="text-lg md:text-xl opacity-70 mb-10 leading-relaxed">
          Standard Operating Procedures quiz results across the team. Sort below to see different views.
        </p>

        {/* Stats summary */}
        {!loading && attempts.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-10">
            <div className="border border-white/10 p-5">
              <div className="text-xs uppercase tracking-widest opacity-60 mb-2">
                Participants
              </div>
              <div className="font-display text-3xl" style={{ color: '#f47820' }}>
                {stats.uniquePeople}
              </div>
            </div>
            <div className="border border-white/10 p-5">
              <div className="text-xs uppercase tracking-widest opacity-60 mb-2">
                Total Attempts
              </div>
              <div className="font-display text-3xl" style={{ color: '#f47820' }}>
                {stats.totalAttempts}
              </div>
            </div>
            <div className="border border-white/10 p-5">
              <div className="text-xs uppercase tracking-widest opacity-60 mb-2">
                Avg. Score
              </div>
              <div className="font-display text-3xl" style={{ color: '#f47820' }}>
                {stats.averagePct}%
              </div>
            </div>
            <div className="border border-white/10 p-5">
              <div className="text-xs uppercase tracking-widest opacity-60 mb-2">
                Top Score
              </div>
              <div className="font-display text-3xl flex items-baseline gap-2" style={{ color: '#f47820' }}>
                <Medal className="w-5 h-5" />
                {stats.highScore
                  ? `${Math.round((stats.highScore.score / stats.highScore.total) * 100)}%`
                  : '—'}
              </div>
              {stats.highScore && (
                <div className="text-xs opacity-60 mt-1 truncate">
                  {stats.highScore.name}
                </div>
              )}
            </div>
          </div>
        )}

        {/* Sort selector */}
        <div className="mb-6">
          <div className="text-xs uppercase tracking-widest opacity-60 mb-3">
            View by
          </div>
          <div className="flex items-stretch gap-2 flex-wrap">
            {SORT_OPTIONS.map(({ key, label, description }) => {
              const active = sortMode === key;
              return (
                <button
                  key={key}
                  onClick={() => setSortMode(key)}
                  className="text-left px-4 py-3 transition-colors flex-1 min-w-[180px]"
                  style={{
                    background: active ? '#f47820' : 'transparent',
                    color: active ? '#0a0a0a' : '#f5f1ea',
                    border: active ? '1px solid #f47820' : '1px solid rgba(245,241,234,0.15)',
                  }}
                >
                  <div className="text-sm uppercase tracking-widest font-semibold">
                    {label}
                  </div>
                  <div className="text-xs mt-0.5" style={{ opacity: active ? 0.75 : 0.55 }}>
                    {description}
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        {error && (
          <div className="border border-red-500/40 p-5 mb-6 text-sm text-red-300 flex items-start gap-2">
            <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
            <span>{error}</span>
          </div>
        )}

        {/* Table */}
        <div className="border border-white/10">
          <div
            className="px-5 py-4 border-b border-orange-500/30 flex items-center justify-between"
            style={{ background: 'rgba(244,120,32,0.08)' }}
          >
            <div className="flex items-center gap-2">
              <Users className="w-5 h-5" style={{ color: '#f47820' }} />
              <div className="text-sm uppercase tracking-[0.3em] font-semibold">
                {SORT_OPTIONS.find((o) => o.key === sortMode)?.label}
              </div>
            </div>
            <div className="text-xs uppercase tracking-widest opacity-60">
              {visibleRows.length} {visibleRows.length === 1 ? 'entry' : 'entries'}
            </div>
          </div>

          {loading ? (
            <div className="p-8 flex items-center gap-3 text-base opacity-70">
              <Loader2 className="w-5 h-5 animate-spin" />
              Loading scoreboard...
            </div>
          ) : visibleRows.length === 0 ? (
            <div className="p-8 text-base opacity-70">
              No scores yet. Be the first to take the quiz.
            </div>
          ) : (
            <div className="divide-y divide-white/10">
              {visibleRows.map((row, idx) => {
                const pct = Math.round((row.score / row.total) * 100);
                const isPodium = sortMode === 'topscore' && idx < 3;
                // For "by person" mode, mark a new section when the name changes
                const isNewPerson = sortMode === 'byperson' && nameStartIndices.has(idx);
                return (
                  <div
                    key={row.id}
                    className="px-5 py-4 flex items-center gap-4 hover:bg-white/[0.02] transition-colors"
                    style={isNewPerson && idx !== 0
                      ? { borderTop: '1px solid rgba(244,120,32,0.2)' }
                      : undefined
                    }
                  >
                    <div
                      className="font-display font-bold text-lg w-8 flex-shrink-0 text-center"
                      style={{ color: isPodium ? '#f47820' : 'rgba(245,241,234,0.4)' }}
                    >
                      {sortMode === 'topscore' ? idx + 1 : ''}
                    </div>
                    {isPodium ? (
                      <Medal className="w-5 h-5 flex-shrink-0" style={{ color: '#f47820' }} />
                    ) : (
                      <div className="w-5 flex-shrink-0" />
                    )}
                    <div className="flex-1 min-w-0">
                      <div className="text-base font-semibold truncate">
                        {row.name}
                      </div>
                      <div className="text-xs opacity-50 mt-0.5 uppercase tracking-wider">
                        {formatDateTime(row.created_at)}
                      </div>
                    </div>
                    <div className="font-display text-lg flex-shrink-0 text-right">
                      <div style={{ color: '#f47820' }}>{pct}%</div>
                      <div className="text-xs opacity-50">
                        {row.score} / {row.total}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
